responses.text:
{
  "outcome": "revise",
  "issues": [
    {
      "kind": "contradiction",
      "severity": "critical",
      "description": "5행에서는 선택한 기록 한 건만 반환 상태로 변경된다고 명시했으나, 9행에서는 선택 항목의 물건명과 같은 모든 기록을 일괄 반환한다고 서술하여 계획 내 동작 설명이 상호 모순됩니다.",
      "suggestedDirection": "9행의 일괄 반환 문구를 삭제하고 5행 및 R-2에 맞추어 선택된 고유 식별자 1건만 반환 상태로 전환되도록 일관되게 수정하십시오.",
      "relatedRequirementId": "R-2"
    },
    {
      "kind": "scope_violation",
      "severity": "critical",
      "description": "승인된 Scope R-2는 '고른 기록 한 건만 반환 상태로 바꾼다'로 한정되어 있으나, 9행에서 동일 물건명을 가진 모든 기록을 일괄 반환하도록 확장 정의하여 승인 범위를 위배했습니다.",
      "suggestedDirection": "동일 물건명 일괄 변경 로직을 배제하고 오직 사용자가 지정한 단일 기록의 상태만 갱신되도록 규정하십시오.",
      "relatedRequirementId": "R-2"
    }
  ],
  "suggestions": [
    "9행의 일괄 반환 문구를 단일 고유 ID 기반 반환 처리로 일원화하십시오."
  ],
  "scopeViolation": true,
  "userJudgmentRequired": false,
  "qualityAssessment": {
    "version": 1,
    "requirements": [
      {
        "requirementId": "R-1",
        "status": "satisfied",
        "evidenceLines": [3, 4, 8],
        "rationale": "공백 제거 검증, 동일 물건명의 개별 등록 허용 및 고유 식별자 부여 규칙이 구체적으로 정의되어 있습니다."
      },
      {
        "requirementId": "R-2",
        "status": "missing",
        "evidenceLines": [5, 9],
        "rationale": "승인 요구사항(한 건만 반환)과 달리 9행에서 동일 물건명 일괄 반환 규칙을 혼용하여 동작 모순 및 범위 위배가 발생했습니다."
      },
      {
        "requirementId": "R-3",
        "status": "satisfied",
        "evidenceLines": [6, 10],
        "rationale": "localStorage 단일 키 직렬화, 깨진 JSON 원본 보존, commit 전후 예외 처리 및 복구 한계가 구체적으로 명시되어 있습니다."
      }
    ],
    "checks": [
      {
        "id": "decision_provenance",
        "status": "satisfied",
        "evidenceLines": [12],
        "rationale": "사용자 결정 출처를 승인 Scope와 제약으로 한정하고 키 이름 등 기술 선택을 위임된 제안으로 명확히 구분했습니다."
      },
      {
        "id": "scope_compliance",
        "status": "missing",
        "evidenceLines": [5, 9],
        "rationale": "R-2에서 단일 기록 반환 범위를 벗어나 동일 물건명 일괄 반환 사양이 포함되어 승인 범위를 위반했습니다."
      },
      {
        "id": "behavior_and_errors",
        "status": "missing",
        "evidenceLines": [5, 9],
        "rationale": "5행의 '한 건만 반환'과 9행의 '동일 물건명 전체 일괄 반환'이 직접적으로 충돌하여 상태 전이 동작이 불일치합니다."
      },
      {
        "id": "data_integrity",
        "status": "satisfied",
        "evidenceLines": [10],
        "rationale": "스키마 검증, 키 부재와 손상 데이터 구분 보존, 쓰기 실패 시 롤백 및 기존 데이터 불변 규칙이 충실히 기술되었습니다."
      },
      {
        "id": "acceptance_criteria",
        "status": "satisfied",
        "evidenceLines": [8, 10],
        "rationale": "등록, 저장 실패, 검증 거부 등 구체적인 입력 조건과 기대 결과가 검증 가능한 형태로 제시되어 있습니다."
      },
      {
        "id": "revision_resolution",
        "status": "not_applicable",
        "evidenceLines": [13],
        "rationale": "초기 기획안 검토 단계로 settledDecisions에 해결해야 할 이전 사용자 수정 요청이 존재하지 않습니다."
      },
      {
        "id": "clarity",
        "status": "satisfied",
        "evidenceLines": [2, 3, 5, 7],
        "rationale": "쉬운 한국어 사용자 관점의 예시가 문서 전면에 선행 배치되어 대상 독자 기준을 충족합니다."
      }
    ]
  }
}
